import { TranslocoModule } from '@jsverse/transloco';
import { SelectorProvider } from '../../../data/selector-provider';
import { debounceTime, distinct, Subscription } from 'rxjs';
import { BaseEditable } from '../base-editable';
import { MatInputModule } from '@angular/material/input';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatIconModule } from '@angular/material/icon';
import { SearchEditable } from '../search-editable';

@Component({
  template: `
    <mat-form-field>
      <mat-label>{{ label() + '.label' | transloco }}</mat-label>
      <input
        matInput
        [required]="required()"
        placeholder="{{ label() + '.placeholder' | transloco }}"
        [matAutocomplete]="auto"
        (blur)="blur()"
        [formControl]="search"
      />
      <span matSuffix style="display: flex">
        <mat-icon *ngIf="!control.disabled" (click)="searchOptions()">keyboard_arrow_down</mat-icon>
      </span>
      <mat-autocomplete
        #auto="matAutocomplete"
        [displayWith]="displayItem()"
        (optionSelected)="optionSelected($event.option.value)"
      >
        <mat-option *ngFor="let item of provider()()" [value]="item">
          {{ provider().display(item) }}
        </mat-option>
      </mat-autocomplete>
      <mat-progress-bar *ngIf="provider().searching()" mode="indeterminate"></mat-progress-bar>
      <mat-error *ngFor="let error of errorMessages()">
        {{ label() + '.error.' + error | transloco }}
      </mat-error>
    </mat-form-field>
  `,
  selector: 'editable-selectone',
  imports: [
    FormsModule,
    MatFormFieldModule,
    MatAutocompleteModule,
    MatInputModule,
    MatIconModule,
    MatProgressBarModule,
    ReactiveFormsModule,
    CommonModule,
    TranslocoModule,
  ],
  providers: BaseEditable.getAccessorProvider(EditableSelectoneComponent),
  standalone: true,
})
export class EditableSelectoneComponent<V, R> extends SearchEditable<V, R> {
  public constructor() {
    super();
    this.bindValueEffect();
  }

  override select(value: R | null): void {
    this.updateValue(value);
  }
}

